  "roomApps.zendeskBodyNote": "変えずにそのまま貼り付けてください。Trina はこの形だけを読みます。",
  "roomApps.copyBody": "本文をコピー",
  "roomApps.saferPreset.typeform": "Typeform で Webhook の {edit} を開き、{secret} にこのシークレットを貼り付けます。以後 Trina は Typeform が署名したものだけを表示します。",
  "roomApps.saferPreset.tally": "Tally で接続する前に {secret} を選びます。Tally 自身のシークレットが入っているので、消してこのシークレットを貼り付けます。以後 Trina は Tally が署名したものだけを表示します。",
  "roomApps.saferPreset.stripe": "Stripe の送信先ページで {reveal} を押し、署名シークレットをコピーしてここに貼り付けます。以後 Trina は Stripe が署名したものだけを表示します。",
  "roomApps.saferPreset.shopify": "Shopify の Webhook ページで {signed} の後にあるキーをコピーしてここに貼り付けます。以後 Trina は Shopify が署名したものだけを表示します。",
  "roomApps.saferPreset.zendesk": "Zendesk の Webhook ページで {reveal} を押し、シークレットをコピーしてここに貼り付けます。以後 Trina は Zendesk が署名したものだけを表示します。",
