  "roomApps.refusedSecret.typeform": "{time} に Typeform からメッセージが届きましたが、シークレットが一致しませんでした。Typeform の Webhook 設定にもう一度貼り付けてください。",
  "roomApps.refusedSecret.tally": "{time} に Tally からメッセージが届きましたが、署名シークレットが一致しませんでした。Tally の Webhook 設定にもう一度貼り付けてください。",
  "roomApps.refusedSecret.stripe": "{time} に Stripe からメッセージが届きましたが、署名シークレットが一致しませんでした。Reveal secret からもう一度コピーしてください。",
  "roomApps.refusedSecret.shopify": "{time} に Shopify からメッセージが届きましたが、署名キーが一致しませんでした。Webhook ページからもう一度コピーしてください。",
  "roomApps.refusedSecret.zendesk": "{time} に Zendesk からメッセージが届きましたが、シークレットが一致しませんでした。Reveal secret からもう一度コピーしてください。",
  "roomApps.newAddressBodyPreset.typeform": "古い URL はすぐに使えなくなり、Typeform は Webhook をオフにします。新しい Webhook URL を Typeform に貼り付けて、Webhook をもう一度オンにしてください。",
  "roomApps.newAddressBodyPreset.shopify": "古い URL はすぐに使えなくなります。Shopify は失敗が続くと Webhook を削除するので、新しい Webhook URL で作り直す必要があるかもしれません。",
  "roomApps.newAddressBodyPreset.notion": "古い URL はすぐに使えなくなり、Notion は自動化を一時停止します。新しい Webhook URL を自動化に貼り付けて再開してください。",
